WITH exploded AS (SELECT id, customer_id, created_at, attr_key, attr_value FROM carts LATERAL VIEW EXPLODE(attributes) e AS attr_key, attr_value) SELECT id, customer_id, created_at, attr_key, attr_value, ROW_NUMBER() OVER (PARTITION BY attr_key ORDER BY created_at DESC, id, attr_key) AS row_seq, ROW_NUMBER() OVER (ORDER BY created_at, id, attr_key) AS seq_no, FIRST_VALUE(attr_key) IGNORE NULLS OVER (PARTITION BY customer_id ORDER BY created_at, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_attr_key FROM exploded;
